import{_ as t,c as e,o as i,ah as l}from"./chunks/framework.CRFddiXd.js";const q=JSON.parse('{"title":"Stuzhik Connect","description":"Stuzhik Connect — прямая P2P-передача модпаков и сборок между друзьями без серверов. Список друзей, коды подключения, безопасность.","frontmatter":{"description":"Stuzhik Connect — прямая P2P-передача модпаков и сборок между друзьями без серверов. Список друзей, коды подключения, безопасность.","head":[["meta",{"name":"keywords","content":"stuzhik connect, стужик коннект, передача модпака другу, p2p minecraft, обмен сборками minecraft, minecraft без сервера"}]]},"headers":[],"relativePath":"guide/connect.md","filePath":"guide/connect.md"}'),o={name:"guide/connect.md"};function r(h,a,n,d,u,c){return i(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="stuzhik-connect" tabindex="-1">Stuzhik Connect <a class="header-anchor" href="#stuzhik-connect" aria-label="Permalink to &quot;Stuzhik Connect&quot;">​</a></h1><p>Прямая передача сборок и модпаков между устройствами — без промежуточных серверов, без загрузки в облако. Файлы идут напрямую от тебя к другу.</p><div class="warning custom-block"><p class="custom-block-title">Важно: работает в пределах одной сети</p><p>Stuzhik сам находит и передаёт файлы устройствам <strong>в одной сети</strong> — обычной домашней/локальной, или виртуальной, поднятой VPN-приложением. У Stuzhik нет собственного сервера для соединения через интернет напрямую, если вы с другом в разных сетях (разные квартиры, города, провайдеры) — большинство домашних роутеров это в принципе блокируют без дополнительных мер.</p><p>Если вы физически в одной сети (один Wi-Fi/локалка) — просто работает. Если в разных — нужен общий VPN, см. <a href="#если-вы-в-разных-сетях">ниже</a>.</p></div><h2 id="включение" tabindex="-1">Включение <a class="header-anchor" href="#включение" aria-label="Permalink to &quot;Включение&quot;">​</a></h2><ol><li>Открой Connect (иконка друзей в сайдбаре)</li><li>Включи тумблер &quot;Включено&quot;</li><li>Появится твой код — 4 символа для передачи устройству, 9 символов (с дефисом) для приглашения на сервер</li></ol><h2 id="подключение-к-другу" tabindex="-1">Подключение к другу <a class="header-anchor" href="#подключение-к-другу" aria-label="Permalink to &quot;Подключение к другу&quot;">​</a></h2><h3 id="по-коду" tabindex="-1">По коду <a class="header-anchor" href="#по-коду" aria-label="Permalink to &quot;По коду&quot;">​</a></h3><ol><li>Попроси у друга его код</li><li>Введи в поле &quot;Код друга или приглашение&quot;</li><li>Нажми &quot;Подключиться&quot;</li></ol><p>Код — это ярлык для устройства <strong>в той же сети</strong> (реальной или VPN), а не универсальный идентификатор для подключения из любой точки интернета: если вы не в одной сети, код тоже не поможет — см. предупреждение выше.</p><h3 id="автопоиск" tabindex="-1">Автопоиск <a class="header-anchor" href="#автопоиск" aria-label="Permalink to &quot;Автопоиск&quot;">​</a></h3><p>Если вы в одной локальной сети, Stuzhik находит устройства друг друга автоматически — код вводить не нужно, устройство появится в списке &quot;Найдено&quot;.</p><h2 id="друзья" tabindex="-1">Друзья <a class="header-anchor" href="#друзья" aria-label="Permalink to &quot;Друзья&quot;">​</a></h2><p>Обнаруженное устройство — ещё не друг. Чтобы добавить:</p><ol><li>Нажми &quot;⋮&quot; рядом с устройством → &quot;Запрос в друзья&quot;</li><li>Друг подтверждает запрос у себя</li><li>После подтверждения устройство помечается как доверенное</li></ol><p>Доверенным друзьям не нужно каждый раз заново находить друг друга — они сохраняются в списке (но найти их снова Stuzhik всё равно сможет только в общей сети).</p><h2 id="передача-фаилов" tabindex="-1">Передача файлов <a class="header-anchor" href="#передача-фаилов" aria-label="Permalink to &quot;Передача файлов&quot;">​</a></h2><h3 id="запросить-у-друга" tabindex="-1">Запросить у друга <a class="header-anchor" href="#запросить-у-друга" aria-label="Permalink to &quot;Запросить у друга&quot;">​</a></h3><ol><li>Найди друга в списке</li><li>&quot;⋮&quot; → &quot;Запросить модпак&quot;</li><li>Выбери, что нужно — модпак целиком, конфиги, ресурспаки, шейдеры</li><li>Друг подтверждает отправку у себя</li></ol><h3 id="отправить-другу" tabindex="-1">Отправить другу <a class="header-anchor" href="#отправить-другу" aria-label="Permalink to &quot;Отправить другу&quot;">​</a></h3><p>Аналогично — из карточки экземпляра или модпака выбери &quot;Отправить другу&quot; и укажи получателя.</p><h3 id="во-время-передачи" tabindex="-1">Во время передачи <a class="header-anchor" href="#во-время-передачи" aria-label="Permalink to &quot;Во время передачи&quot;">​</a></h3><ul><li>Прогресс виден во вкладке &quot;Передачи&quot;</li><li>Прерванную передачу можно возобновить — заново перекачивать не нужно</li><li>Пауза/отмена доступны в любой момент</li><li>После скачивания хеши файлов проверяются автоматически</li></ul><h2 id="если-вы-в-разных-сетях" tabindex="-1">Если вы в разных сетях <a class="header-anchor" href="#если-вы-в-разных-сетях" aria-label="Permalink to &quot;Если вы в разных сетях&quot;">​</a></h2><p>Домашние роутеры и мобильный интернет почти всегда блокируют прямое соединение между разными сетями — так работает NAT, это не баг Stuzhik и не то, что мы можем обойти сами. Рабочий вариант — виртуальная локальная сеть поверх интернета: ставите одно и то же VPN-приложение оба, оно объединяет ваши устройства в общую (виртуальную) сеть, и дальше Connect работает как в обычной локалке.</p><p>Мы не разрабатываем и не поддерживаем эти приложения — просто рекомендация того, что сами используем и что работает:</p><table tabindex="0"><thead><tr><th>Вариант</th><th>Сложность</th></tr></thead><tbody><tr><td>Radmin VPN</td><td>Лёгкая</td></tr><tr><td>ZeroTier</td><td>Лёгкая</td></tr><tr><td>Tailscale</td><td>Средняя</td></tr></tbody></table><p>Подсказки по этим вариантам есть прямо в настройках Connect (без внешних ссылок — только названия, чтобы найти самим).</p><h2 id="безопасность" tabindex="-1">Безопасность <a class="header-anchor" href="#безопасность" aria-label="Permalink to &quot;Безопасность&quot;">​</a></h2><ul><li>Соединение между устройствами шифруется, обмен ключами происходит при первом рукопожатии</li><li>Файлы передаются только после явного подтверждения получателя — ничего не приходит без спроса</li><li>Заблокированный пир не может отправлять запросы и не виден в поиске</li><li>Видимость настраивается: можно скрыть себя из поиска для всех, кроме уже добавленных друзей</li></ul><h2 id="решение-проблем" tabindex="-1">Решение проблем <a class="header-anchor" href="#решение-проблем" aria-label="Permalink to &quot;Решение проблем&quot;">​</a></h2><h3 id="друг-не-находится-в-сети" tabindex="-1">Друг не находится в сети <a class="header-anchor" href="#друг-не-находится-в-сети" aria-label="Permalink to &quot;Друг не находится в сети&quot;">​</a></h3><ol><li>Оба точно включили Connect?</li><li>Вы точно в одной сети — физической или через общий VPN? (Автопоиск и подключение по коду видят только устройства в той же сети, см. предупреждение в начале страницы)</li><li>Проверь, что VPN-приложение (если используете) реально подключено у обоих, а не просто установлено</li></ol><h3 id="передача-зависла" tabindex="-1">Передача зависла <a class="header-anchor" href="#передача-зависла" aria-label="Permalink to &quot;Передача зависла&quot;">​</a></h3><ol><li>Проверь вкладку &quot;Передачи&quot; — статус может быть &quot;на паузе&quot;</li><li>Возобнови вручную</li><li>Если не помогает — отмени и запроси заново, хеш повреждённой части не потеряется</li></ol><h3 id="не-приходит-запрос-в-друзья" tabindex="-1">Не приходит запрос в друзья <a class="header-anchor" href="#не-приходит-запрос-в-друзья" aria-label="Permalink to &quot;Не приходит запрос в друзья&quot;">​</a></h3><p>Убедись, что видимость не выставлена в &quot;Только друзья&quot; — в этом режиме новые (ещё не добавленные) устройства не видят тебя вовсе.</p><h2 id="что-дальше" tabindex="-1">Что дальше? <a class="header-anchor" href="#что-дальше" aria-label="Permalink to &quot;Что дальше?&quot;">​</a></h2><ul><li><a href="/guide/modpacks.html">Модпаки</a></li><li><a href="/guide/collections.html">Сборки модов</a></li><li><a href="/faq.html">FAQ</a></li></ul>',38)])])}const b=t(o,[["render",r]]);export{q as __pageData,b as default};
